    f(1)
    f(2)
    f(1)  # touch 1
    f(3)  # evict 2
    assert f.cache_info().currsize == 2
    before = f.cache_info().misses
    f(1)  # hit
    assert f.cache_info().hits == 2
    f(2)  # miss (evicted)
    assert f.cache_info().misses == before + 1


